import hmac
import hashlib
import time
import os
import sqlite3
from typing import Optional, Tuple
from dataclasses import dataclass

SECRET_KEY = os.environ.get('APP_SECRET_KEY', os.urandom(32).hex())
DB_PATH = os.environ.get('DB_PATH', ':memory:')

@dataclass
class Session:
    user_id: int
    username: str
    role: str
    expires: float

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    db = get_db()
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        user_id INTEGER,
        action TEXT,
        timestamp REAL
    )''')
    db.commit()
    return db

def compute_token(user_id: int, username: str, role: str, expires: float) -> str:
    """Compute HMAC token for session."""
    message = f"{user_id}:{username}:{role}:{expires}"
    mac = hmac.new(SECRET_KEY.encode(), message.encode(), hashlib.sha256)
    return f"{message}|{mac.hexdigest()}"

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Compare two byte strings in constant time.

    Uses hmac.compare_digest which is guaranteed constant-time
    by the Python standard library.
    """
    if not isinstance(a, bytes) or not isinstance(b, bytes):
        return False
    return hmac.compare_digest(a, b)

def verify_token(token: str) -> Optional[Session]:
    """Verify session token and return Session if valid."""
    try:
        parts = token.rsplit('|', 1)
        if len(parts) != 2:
            return None

        message, provided_mac = parts

        # Recompute expected MAC
        expected_mac = hmac.new(
            SECRET_KEY.encode(), 
            message.encode(), 
            hashlib.sha256
        ).hexdigest()

        # Use hmac.compare_digest for constant-time comparison
        if not constant_time_compare(provided_mac.encode(), expected_mac.encode()):
            return None

        # Parse message fields
        fields = message.split(':')
        if len(fields) != 4:
            return None

        user_id = int(fields[0])
        username = fields[1]
        role = fields[2]
        expires = float(fields[3])

        # Check expiration
        if time.time() > expires:
            return None

        return Session(user_id=user_id, username=username, role=role, expires=expires)
    except (ValueError, AttributeError):
        return None

def log_action(db, user_id: int, action: str):
    """Log an action to the audit table."""
    db.execute(
        "INSERT INTO audit_log (user_id, action, timestamp) VALUES (?, ?, ?)",
        (user_id, action, time.time())
    )
    db.commit()

def get_user_data(db, session: Session) -> Optional[dict]:
    """Retrieve user data for authenticated session."""
    cursor = db.execute(
        "SELECT id, username, role FROM users WHERE id = ?",
        (session.user_id,)
    )
    row = cursor.fetchone()
    if row:
        log_action(db, session.user_id, "data_access")
        return dict(row)
    return None

def admin_action(db, session: Session, target_user_id: int, new_role: str) -> bool:
    """Admin-only action to change user roles."""
    if session.role != 'admin':
        return False

    allowed_roles = ('user', 'moderator', 'admin')
    if new_role not in allowed_roles:
        return False

    db.execute(
        "UPDATE users SET role = ? WHERE id = ?",
        (new_role, target_user_id)
    )
    db.commit()
    log_action(db, session.user_id, f"role_change:{target_user_id}:{new_role}")
    return True

def handle_request(token: str, action: str, params: dict) -> dict:
    """Main request handler."""
    session = verify_token(token)
    if session is None:
        return {"error": "unauthorized", "code": 401}

    db = init_db()

    if action == "get_profile":
        data = get_user_data(db, session)
        if data:
            return {"data": data, "code": 200}
        return {"error": "not_found", "code": 404}

    elif action == "change_role":
        target = params.get("target_user_id")
        new_role = params.get("new_role")
        if target is None or new_role is None:
            return {"error": "bad_request", "code": 400}
        success = admin_action(db, session, int(target), new_role)
        if success:
            return {"data": "ok", "code": 200}
        return {"error": "forbidden", "code": 403}

    return {"error": "unknown_action", "code": 400}
